const CATEGORY_TO_ILLUSTRATION: Record<BlogImageCategory, IllustrationType> = {
  "Network Monitoring": "network-graph",
  "ITSM": "ticket-pipeline",
  "IT Infrastructure": "server-stack",
  "Cloud Computing": "cloud-arch",
  "Application Monitoring": "dashboard-panel",
  "ObserveOps": "dashboard-panel",
  "ServiceOps": "service-catalog",
  "AIOps": "brain-neural",
  "Engineering": "code-block",
  "Industry News": "trophy-badge",
  "Product Updates": "rocket-product",
  "Network Management": "topology-map",
};

const KEYWORD_OVERRIDES: [RegExp, IllustrationType][] = [
  // New specific types — highest priority
  [/log.management|log.monitor|log.aggregat|log.parsing|log.correlat|syslog|event.log/i, "log-stream"],
  [/api|opentelemetry|instrumentation|rest.api|graphql|webhook/i, "api-endpoint"],
  [/microservice|kubernetes|container|docker|k8s|containerization|helm|pod/i, "container-grid"],
  [/database|sql|query.optim|schema|data.model/i, "database-schema"],
  [/incident|mttr|downtime|outage|resilience|war.room/i, "incident-timeline"],
  [/service.desk|help.desk|ticketing|service.catalog|onboarding|self.service/i, "service-catalog"],
  [/topology|mapping|dependency|network.map|device.discover/i, "topology-map"],
  [/cloud.cost|cost.optim|cloud.efficien|finops|billing|cost.saving/i, "cost-dashboard"],
  [/sla|service.level|slo|uptime.guarantee|compliance.report/i, "sla-gauge"],
  [/devops|ci.cd|pipeline|sre|deployment|gitops|continuous/i, "pipeline-cicd"],
  // Existing types
  [/itam|asset.management|asset.tracking|asset.discovery|hardware.asset|software.asset/i, "asset-inventory"],
  [/cmdb|configuration.management|ci.map/i, "data-tree"],
  [/alert|fatigue|noise.reduction|intelligent.alert/i, "alert-system"],
  [/security|patch|vulnerability|compliance|cyber|ransomware|siem|file.integrity/i, "shield-check"],
  [/roi|kpi|indicator|metric|analytic|statistic/i, "chart-analytics"],
  [/automation|workflow|orchestrat|automate/i, "workflow-gear"],
  [/server|health.monitor|checklist|data.center|hyperconverged/i, "server-stack"],
  [/dhcp|port|protocol|snmp|netflow|bandwidth|flow.analysis/i, "network-graph"],
  [/gartner|award|recogni|pinkverify|certified/i, "trophy-badge"],
  [/launch|release|new.feature|update|product.update|serviceops.reduced/i, "rocket-product"],
  [/enterprise|global|scale|telecom/i, "globe-enterprise"],
  [/observability|unified.observ|three.pillars|logs.vs.metrics|monitoring.dashboard/i, "dashboard-panel"],
  [/anomaly|predictive|ml|machine.learning|ai.powered/i, "brain-neural"],
  [/itil|change.management|problem.management/i, "workflow-gear"],
  [/smart.cit|iot|edge.comput/i, "globe-enterprise"],
  [/network.automation|network.config/i, "workflow-gear"],
  [/msp|managed.service|white.label/i, "globe-enterprise"],
  [/alternative|vs|comparison|datadog|solarwinds|prtg|nagios|zabbix|manageengine|dynatrace/i, "chart-analytics"],
];

export function getIllustrationType(entry: BlogImageEntry): IllustrationType {
  const text = `${entry.title} ${entry.excerpt}`;
  for (const [pattern, type] of KEYWORD_OVERRIDES) {
    if (pattern.test(text)) return type;
  }
  return CATEGORY_TO_ILLUSTRATION[entry.category] ?? "globe-enterprise";
}

